<?php require 'header.php';role_required(['ADMIN']);if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO products(sku,product_name,product_type,unit,purchase_price,selling_price,minimum_stock,description) VALUES(?,?,?,?,?,?,?,?)')->execute([trim($_POST['sku']),trim($_POST['name']),$_POST['type'],trim($_POST['unit']),$_POST['buy'],$_POST['sell'],$_POST['minimum'],trim($_POST['description'])]);flash('Data barang berhasil ditambahkan.');header('Location:products.php');exit;}$items=$pdo->query('SELECT sku,product_name,product_type,unit,minimum_stock FROM products ORDER BY product_id DESC')->fetchAll();?><div class="page-intro"><div><h2>Master barang</h2><p>Kelola material, komponen, dan produk jadi alternator.</p></div><span class="role-note">Admin access</span></div><div class="two-col"><section class="panel form-panel"><div class="panel-head"><div><h3>Tambah barang baru</h3><p>Lengkapi informasi sebelum menyimpan.</p></div></div><form method="post" class="form-grid"><label>SKU / kode barang<input name="sku" placeholder="Contoh: RM-CU-001" required></label><label>Nama barang<input name="name" placeholder="Nama material atau produk" required></label><label>Jenis barang<select name="type"><option value="RAW_MATERIAL">Bahan baku</option><option value="FINISHED_GOOD">Barang jadi</option><option value="SUPPORTING_MATERIAL">Material pendukung</option></select></label><label>Satuan<input name="unit" value="PCS" required></label><label>Harga beli<input type="number" name="buy" min="0" value="0"></label><label>Harga jual<input type="number" name="sell" min="0" value="0"></label><label>Stok minimum<input type="number" name="minimum" min="0" value="0" required></label><label>Deskripsi<input name="description" placeholder="Keterangan singkat"></label><div class="form-action"><button class="primary">+ Simpan barang</button></div></form></section><section class="panel list-panel"><div class="panel-head"><div><h3>Daftar barang</h3><p><?=count($items)?> data tersedia</p></div></div><div class="table-wrap table-short"><table><thead><tr><th>Barang</th><th>Jenis</th><th>Min.</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><code><?=e($x['sku'])?></code><br><b><?=e($x['product_name'])?></b><small><?=e($x['unit'])?></small></td><td><span class="badge neutral"><?=e(str_replace('_',' ',$x['product_type']))?></span></td><td><?=e($x['minimum_stock'])?></td></tr><?php endforeach?></tbody></table></div></section></div><?php require 'footer.php';?>